(() => {
  'use strict';
  if (!/\/admin\.html$/i.test(location.pathname)) return;

  const API = 'https://sulandra-website-production-5fc4.up.railway.app';
  const token = () => sessionStorage.getItem('sulandra:employee:access-token')
    || localStorage.getItem('sulandra:employee:access-token')
    || localStorage.getItem('sulandra_token')
    || localStorage.getItem('token')
    || localStorage.getItem('accessToken')
    || '';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, char => char.toUpperCase());
  const date = value => value ? new Date(value).toLocaleDateString() : '—';
  const dateTime = value => value ? new Date(value).toLocaleString() : '—';
  const statusClass = value => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const number = value => value == null || value === '' ? '—' : Number(value).toFixed(Number(value) % 1 ? 2 : 0);
  const toInputDate = value => value ? new Date(value).toISOString().slice(0,10) : '';
  const toInputDateTime = value => value ? new Date(value).toISOString().slice(0,16) : '';

  let state = null;
  let activeTab = 'dashboard';
  let selectedEmployeeId = null;
  let selectedReview = null;
  let selectedTemplate = null;
  let installScheduled = false;

  async function api(path, options = {}) {
    const auth = token();
    if (!auth) throw new Error('Your admin session is unavailable. Sign in again.');
    const response = await fetch(API + path, {
      ...options,
      cache: 'no-store',
      headers: {
        Accept: options.accept || 'application/json',
        Authorization: `Bearer ${auth}`,
        ...(options.body ? {'Content-Type':'application/json'} : {}),
        ...(options.headers || {})
      }
    });
    if (options.raw) {
      if (!response.ok) throw new Error((await response.json().catch(()=>({}))).error || 'Request failed');
      return response;
    }
    const body = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(body.error || 'Request failed');
    return body.data ?? body;
  }

  function addStyles() {
    if (document.getElementById('adminPerformanceStyles')) return;
    const style = document.createElement('style');
    style.id = 'adminPerformanceStyles';
    style.textContent = `
      #employeePerformanceOverlay{position:fixed;inset:0;background:rgba(14,17,37,.75);z-index:10140;display:none;padding:18px;overflow:auto;color:#263847;font-family:inherit}#employeePerformanceOverlay.open{display:block}
      .ap-shell{width:min(1540px,100%);margin:0 auto;background:#f5f7fa;border-radius:12px;box-shadow:0 24px 70px rgba(0,0,0,.38);overflow:hidden;min-height:calc(100vh - 36px)}
      .ap-head{background:linear-gradient(135deg,#411766,#7d3cb5);color:#fff;padding:18px 22px;display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.ap-head h2{margin:0;color:#fff;font-size:28px}.ap-head p{margin:5px 0 0;opacity:.94}.ap-actions{display:flex;gap:8px;flex-wrap:wrap}
      .ap-btn{appearance:none;border:1px solid #6b319d;background:#fff;color:#542681;border-radius:7px;padding:9px 13px;font-weight:800;cursor:pointer;font-size:14px;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.ap-btn.primary{background:#6c32a0;color:#fff}.ap-btn.danger{background:#bf3d2d;border-color:#bf3d2d;color:#fff}.ap-btn.warn{background:#fff0bf;border-color:#d1a018;color:#6f4f00}.ap-btn.success{background:#1f7a46;border-color:#1f7a46;color:#fff}.ap-btn:disabled{opacity:.5;cursor:not-allowed}
      .ap-tabs{display:flex;overflow:auto;background:#e9e0f2;border-bottom:1px solid #cbb9da;scrollbar-width:none}.ap-tabs::-webkit-scrollbar{display:none}.ap-tab{border:0;border-right:1px solid #cbb9da;background:transparent;color:#57317b;padding:12px 15px;font-weight:900;cursor:pointer;white-space:nowrap}.ap-tab.active{background:#fff;color:#421968}
      .ap-status{display:none;margin:14px 18px 0;padding:10px 12px;border:1px solid #e0c15b;background:#fff6d8;border-radius:7px}.ap-status.show{display:block}.ap-status.error{background:#fde6e2;border-color:#d87866;color:#8f2519}.ap-body{padding:18px}.ap-metrics{display:grid;grid-template-columns:repeat(8,minmax(135px,1fr));gap:10px;margin-bottom:16px}.ap-card{background:#fff;border:1px solid #d1dbe4;border-radius:9px;padding:13px}.ap-card h3,.ap-card h4{margin:0 0 7px;color:#542681}.ap-metric{font-size:27px;font-weight:900;color:#5d2c8e}.ap-sub{font-size:12px;color:#687785;margin-top:4px}.ap-grid{display:grid;grid-template-columns:repeat(2,minmax(260px,1fr));gap:13px}.ap-grid.three{grid-template-columns:repeat(3,minmax(200px,1fr))}
      .ap-section{margin-top:18px}.ap-section h3{margin:0 0 10px;color:#542681}.ap-list{background:#fff;border:1px solid #d1dbe4;border-radius:9px;overflow:hidden}.ap-row{display:flex;justify-content:space-between;gap:13px;align-items:flex-start;padding:12px;border-top:1px solid #e1e7ed}.ap-row:first-child{border-top:0}.ap-title{font-weight:900;color:#3d2254}.ap-row-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.ap-badge{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:12px;font-weight:900;background:#eee6f7;color:#542681;margin:2px}.ap-badge.completed,.ap-badge.active,.ap-badge.approved,.ap-badge.successfullycompleted{background:#def4e5;color:#176b35}.ap-badge.atrisk,.ap-badge.overdue,.ap-badge.rejected,.ap-badge.unsuccessful,.ap-badge.finalwarning{background:#fde1dc;color:#9e2415}.ap-badge.employeeinput,.ap-badge.managerreview,.ap-badge.calibration,.ap-badge.acknowledgment,.ap-badge.pendingapproval,.ap-badge.extended,.ap-badge.open{background:#fff0c4;color:#705100}
      .ap-table-wrap{overflow:auto;background:#fff;border:1px solid #cbd7e1;border-radius:9px}.ap-table{width:100%;border-collapse:collapse;min-width:1150px}.ap-table th{background:#ebe4f2;color:#3f215d;text-align:left;padding:10px;border-bottom:1px solid #c7b9d4;position:sticky;top:0}.ap-table td{padding:10px;border-bottom:1px solid #e1e7ed;vertical-align:top}.ap-table tr[data-ap-employee]{cursor:pointer}.ap-table tr[data-ap-employee]:hover{background:#faf7fd}
      .ap-input,.ap-select,.ap-textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #b8c6d2;border-radius:7px;background:#fff;font:inherit}.ap-textarea{min-height:100px;resize:vertical}.ap-form label{display:block;font-size:13px;font-weight:800;color:#34495e}.ap-form-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.ap-empty{text-align:center;padding:34px;border:2px dashed #cbb8dc;border-radius:10px;background:#fbf8fe}.ap-alert{border:1px solid #dfbf5f;background:#fff7dc;border-radius:8px;padding:12px;margin-bottom:12px}.ap-alert.danger{border-color:#d77a69;background:#fde7e3}.ap-alert.success{border-color:#8bc69d;background:#eefaf1}
      .ap-progress{height:10px;background:#e9edf1;border-radius:999px;overflow:hidden;margin-top:6px}.ap-progress span{display:block;height:100%;background:linear-gradient(90deg,#6b319d,#a76bd0)}
      .ap-modal{position:fixed;inset:0;background:rgba(13,20,38,.72);z-index:10160;display:none;align-items:flex-start;justify-content:center;padding:18px;overflow:auto}.ap-modal.open{display:flex}.ap-dialog{width:min(1040px,100%);background:#fff;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.38);overflow:hidden;margin:auto}.ap-dialog.wide{width:min(1320px,100%)}.ap-dialog-head{background:#421968;color:#fff;padding:16px 19px;display:flex;justify-content:space-between;align-items:center;gap:12px}.ap-dialog-head h3{margin:0;color:#fff}.ap-dialog-body{padding:18px;max-height:80vh;overflow:auto}.ap-close{border:0;background:#fff;color:#421968;border-radius:6px;padding:8px 12px;font-weight:900;cursor:pointer}.ap-rating-row{display:grid;grid-template-columns:minmax(180px,1fr) 140px 2fr;gap:10px;align-items:start;padding:11px;border-top:1px solid #e2e8ee}.ap-rating-row:first-child{border-top:0}.ap-template-competency{display:grid;grid-template-columns:120px 1fr 110px 2fr auto;gap:8px;align-items:end;border:1px solid #d3dce5;border-radius:8px;padding:9px;margin-top:8px}.ap-dev{border-left:5px solid #6b319d}.ap-pip{border-left:5px solid #bf3d2d}.ap-timeline{margin:8px 0 0 6px;padding-left:20px;border-left:2px solid #d2c3df}.ap-step{padding:0 0 13px}.ap-step:last-child{padding-bottom:0}.ap-profile-performance{margin-left:6px}
      @media(max-width:1200px){.ap-metrics{grid-template-columns:repeat(4,1fr)}.ap-grid,.ap-grid.three{grid-template-columns:1fr 1fr}.ap-template-competency{grid-template-columns:100px 1fr 100px}.ap-template-competency>*:nth-child(4),.ap-template-competency>*:nth-child(5){grid-column:auto}}
      @media(max-width:780px){#employeePerformanceOverlay{padding:0}.ap-shell{border-radius:0;min-height:100vh}.ap-head{flex-direction:column;padding:16px}.ap-head h2{font-size:24px}.ap-body{padding:12px}.ap-metrics,.ap-grid,.ap-grid.three{grid-template-columns:1fr}.ap-row{flex-direction:column}.ap-row-actions,.ap-actions,.ap-form-actions{width:100%;justify-content:flex-start}.ap-row-actions .ap-btn,.ap-actions .ap-btn,.ap-form-actions .ap-btn{flex:1}.ap-modal{padding:6px}.ap-dialog{border-radius:8px}.ap-dialog-body{max-height:none}.ap-rating-row,.ap-template-competency{grid-template-columns:1fr}}
    `;
    document.head.appendChild(style);
  }

  function shell() {
    return `<div id="employeePerformanceOverlay"><div class="ap-shell"><div class="ap-head"><div><h2>Employee 360 Performance Center</h2><p>Review cycles, goals, manager assessments, calibration, development planning, formal action plans, reporting, and employee acknowledgments.</p></div><div class="ap-actions"><button class="ap-btn" id="apRefresh">Refresh</button><button class="ap-btn" id="apClose">Close Performance Center</button></div></div><div class="ap-tabs">${[['dashboard','Dashboard'],['reviews','Reviews'],['team','Team'],['goals','Goals'],['development','Development'],['actions','Action Plans'],['cycles','Review Cycles'],['templates','Templates']].map(([id,name])=>`<button class="ap-tab ${activeTab===id?'active':''}" data-ap-tab="${id}">${name}</button>`).join('')}</div><div id="apStatus" class="ap-status"></div><div id="apBody" class="ap-body"></div></div></div><div class="ap-modal" id="apModal"><div class="ap-dialog wide" id="apDialog"><div class="ap-dialog-head"><h3 id="apModalTitle">Employee Performance</h3><button class="ap-close" id="apModalClose">Close</button></div><div class="ap-dialog-body" id="apModalBody"></div></div></div>`;
  }

  function setStatus(message,error=false){const box=document.getElementById('apStatus');if(!box)return;box.textContent=message;box.classList.toggle('show',Boolean(message));box.classList.toggle('error',error)}
  function openModal(title,body,wide=true){document.getElementById('apModalTitle').textContent=title;document.getElementById('apModalBody').innerHTML=body;document.getElementById('apDialog').classList.toggle('wide',wide);document.getElementById('apModal').classList.add('open')}
  function closeModal(){document.getElementById('apModal')?.classList.remove('open');selectedReview=null;selectedTemplate=null}

  function installOverlay(){if(document.getElementById('employeePerformanceOverlay'))return;addStyles();document.body.insertAdjacentHTML('beforeend',shell());document.getElementById('apClose').onclick=closeCenter;document.getElementById('apRefresh').onclick=load;document.getElementById('apModalClose').onclick=closeModal;document.getElementById('apModal').addEventListener('click',event=>{if(event.target.id==='apModal')closeModal()});document.querySelectorAll('[data-ap-tab]').forEach(button=>button.onclick=()=>{activeTab=button.dataset.apTab;render()})}

  function installButtons(){const e360=document.getElementById('employee360');if(!e360)return;const actions=e360.querySelector('.e360-head .e360-actions');if(actions&&!document.getElementById('openEmployeePerformance')){const button=document.createElement('button');button.id='openEmployeePerformance';button.className='e360-btn primary';button.type='button';button.textContent='Performance';button.onclick=openCenter;actions.prepend(button)}const profileActions=e360.querySelector('.e360-profile-head .e360-actions');if(profileActions&&selectedEmployeeId&&!document.getElementById('openProfilePerformance')){const button=document.createElement('button');button.id='openProfilePerformance';button.className='e360-btn ap-profile-performance';button.type='button';button.textContent='Performance';button.onclick=()=>openEmployee(selectedEmployeeId);profileActions.prepend(button)}}

  async function openCenter(){installOverlay();document.getElementById('employeePerformanceOverlay').classList.add('open');history.replaceState(null,'',`${location.pathname}${location.search}#employeePerformance`);await load()}
  function closeCenter(){document.getElementById('employeePerformanceOverlay')?.classList.remove('open');if(location.hash==='#employeePerformance')history.replaceState(null,'',`${location.pathname}${location.search}`)}

  async function load(){try{setStatus('Loading Performance Center…');state=await api('/api/admin/employee-performance/dashboard');render();setStatus('')}catch(error){setStatus(error.message,true);document.getElementById('apBody').innerHTML=`<div class="ap-empty"><h3>Performance Center is unavailable</h3><p>${esc(error.message)}</p></div>`}}

  function render(){if(!state)return;document.querySelectorAll('[data-ap-tab]').forEach(button=>button.classList.toggle('active',button.dataset.apTab===activeTab));const views={dashboard:dashboardView,reviews:reviewsView,team:teamView,goals:goalsView,development:developmentView,actions:actionView,cycles:cyclesView,templates:templatesView};document.getElementById('apBody').innerHTML=views[activeTab]();wire()}
  const metric=(title,value,subtitle)=>`<div class="ap-card"><h4>${esc(title)}</h4><div class="ap-metric">${Number(value||0)}</div><div class="ap-sub">${esc(subtitle)}</div></div>`;

  function dashboardView(){const m=state.metrics||{};const pending=state.reviews.filter(row=>['EMPLOYEE_INPUT','MANAGER_REVIEW','CALIBRATION','ACKNOWLEDGMENT'].includes(row.status)).slice(0,10);const atRisk=state.goals.filter(row=>row.status==='AT_RISK'||(row.dueDate&&new Date(row.dueDate)<new Date()&&row.status!=='COMPLETED')).slice(0,10);return `<div class="ap-metrics">${metric('Employees in Scope',m.teamCount,'Role and service-location scope')}${metric('Open Reviews',m.openReviewCount,'Reviews not completed or cancelled')}${metric('Manager Reviews',m.pendingManagerReviewCount,'Manager assessments required')}${metric('Acknowledgments',m.pendingAcknowledgmentCount,'Final reviews awaiting employee receipt')}${metric('Goals at Risk',m.goalsAtRiskCount,'Late or marked at risk')}${metric('Development Plans',m.activeDevelopmentPlanCount,'Active employee growth plans')}${metric('Action Plans',m.activeActionPlanCount,'Active formal improvement plans')}${metric('Completed Reviews',m.completedReviewCount,'Completed performance records')}</div><div class="ap-grid"><div><h3>Review Work Queue</h3>${pending.length?`<div class="ap-list">${pending.map(reviewRow).join('')}</div>`:'<div class="ap-empty">No reviews currently require attention.</div>'}</div><div><h3>Goals Requiring Attention</h3>${atRisk.length?`<div class="ap-list">${atRisk.map(goalRow).join('')}</div>`:'<div class="ap-empty">No goals currently require attention.</div>'}</div></div>`}

  function reviewRow(row){return `<div class="ap-row"><div><div class="ap-title">${esc(row.employeeName||row.employeeId)} — ${esc(row.cycleName||'Performance Review')}</div><div class="ap-sub">${date(row.periodStart)} – ${date(row.periodEnd)} · Manager ${esc(row.managerId||'Not assigned')} · Final rating ${number(row.finalRating)}</div><span class="ap-badge ${statusClass(row.status)}">${label(row.status)}</span></div><div class="ap-row-actions"><button class="ap-btn" data-review="${esc(row.id)}">Open Review</button><button class="ap-btn" data-employee="${esc(row.employeeId)}">Employee</button></div></div>`}
  function reviewsView(){return `<div class="ap-grid three" style="margin-bottom:13px"><label>Search<input class="ap-input" id="apReviewSearch" placeholder="Employee, cycle, status"></label><label>Status<select class="ap-select" id="apReviewStatus"><option value="">All statuses</option>${['EMPLOYEE_INPUT','MANAGER_REVIEW','CALIBRATION','ACKNOWLEDGMENT','COMPLETED','CANCELLED'].map(value=>`<option>${value}</option>`).join('')}</select></label><label>Cycle<select class="ap-select" id="apReviewCycle"><option value="">All cycles</option>${state.cycles.map(row=>`<option value="${esc(row.id)}">${esc(row.name)}</option>`).join('')}</select></label></div><div id="apReviewList"></div>`}
  function renderReviewList(){const box=document.getElementById('apReviewList');if(!box)return;const q=String(document.getElementById('apReviewSearch')?.value||'').toLowerCase();const status=document.getElementById('apReviewStatus')?.value||'';const cycle=document.getElementById('apReviewCycle')?.value||'';const rows=state.reviews.filter(row=>(!q||[row.employeeName,row.cycleName,row.status].some(value=>String(value||'').toLowerCase().includes(q)))&&(!status||row.status===status)&&(!cycle||row.cycleId===cycle));box.innerHTML=rows.length?`<div class="ap-list">${rows.map(reviewRow).join('')}</div>`:'<div class="ap-empty">No reviews match these filters.</div>';wireCommon(box)}

  function teamView(){return `<div class="ap-grid" style="margin-bottom:13px"><label>Search team<input class="ap-input" id="apTeamSearch" placeholder="Name, email, role, title or department"></label><label>Performance risk<select class="ap-select" id="apTeamRisk"><option value="">All employees</option><option value="reviews">Open reviews</option><option value="manager">Manager assessment due</option><option value="goals">Goals at risk</option><option value="development">Active development plan</option><option value="action">Active action plan</option></select></label></div><div id="apTeamTable"></div>`}
  function renderTeam(){const box=document.getElementById('apTeamTable');if(!box)return;const q=String(document.getElementById('apTeamSearch')?.value||'').toLowerCase();const risk=document.getElementById('apTeamRisk')?.value||'';const rows=state.team.filter(row=>(!q||[row.displayName,row.email,row.role,row.jobTitle,row.department].some(value=>String(value||'').toLowerCase().includes(q)))&&(!risk||(risk==='reviews'&&row.activeReviewCount)||(risk==='manager'&&row.pendingManagerReviewCount)||(risk==='goals'&&row.goalsAtRiskCount)||(risk==='development'&&row.activeDevelopmentPlanCount)||(risk==='action'&&row.activeActionPlanCount)));if(!rows.length){box.innerHTML='<div class="ap-empty">No employees match these filters.</div>';return}box.innerHTML=`<div class="ap-table-wrap"><table class="ap-table"><thead><tr><th>Employee</th><th>Position</th><th>Reviews</th><th>Manager Queue</th><th>Acknowledgments</th><th>Goals</th><th>Development</th><th>Action Plans</th><th>Latest Rating</th></tr></thead><tbody>${rows.map(row=>`<tr data-ap-employee="${esc(row.id)}"><td><div class="ap-title">${esc(row.displayName)}</div><div class="ap-sub">${esc(row.email||'')}</div></td><td>${esc(row.jobTitle||label(row.role))}<div class="ap-sub">${esc(row.department||'No department')}</div></td><td>${Number(row.activeReviewCount||0)}</td><td><span class="ap-badge ${row.pendingManagerReviewCount?'managerreview':''}">${Number(row.pendingManagerReviewCount||0)}</span></td><td>${Number(row.pendingAcknowledgmentCount||0)}</td><td>${Number(row.activeGoalCount||0)} active<br><span class="ap-badge ${row.goalsAtRiskCount?'atrisk':'active'}">${Number(row.goalsAtRiskCount||0)} at risk</span></td><td>${Number(row.activeDevelopmentPlanCount||0)}</td><td><span class="ap-badge ${row.activeActionPlanCount?'atrisk':'active'}">${Number(row.activeActionPlanCount||0)}</span></td><td>${number(row.latestRating)}</td></tr>`).join('')}</tbody></table></div>`;box.querySelectorAll('[data-ap-employee]').forEach(row=>row.onclick=()=>openEmployee(row.dataset.apEmployee))}

  function goalRow(row){const employee=state.team.find(item=>item.id===row.employeeId);return `<div class="ap-row"><div style="flex:1"><div class="ap-title">${esc(employee?.displayName||row.employeeId)} — ${esc(row.title)}</div><div class="ap-sub">${label(row.category)} · Due ${date(row.dueDate)} · Target ${row.targetValue==null?'Milestone':`${number(row.targetValue)} ${esc(row.unit||'')}`}</div><div class="ap-progress"><span style="width:${Math.max(0,Math.min(100,Number(row.progressPercent||0)))}%"></span></div><div class="ap-sub">${number(row.progressPercent)}% complete</div><span class="ap-badge ${statusClass(row.status)}">${label(row.status)}</span></div><div class="ap-row-actions"><button class="ap-btn" data-edit-goal="${esc(row.id)}">Edit</button><button class="ap-btn" data-employee="${esc(row.employeeId)}">Employee</button></div></div>`}
  function goalsView(){return `<div class="ap-actions" style="margin-bottom:13px"><button class="ap-btn primary" id="apCreateGoal">Assign Goal</button></div><div class="ap-grid three" style="margin-bottom:13px"><label>Search<input class="ap-input" id="apGoalSearch" placeholder="Employee or goal"></label><label>Status<select class="ap-select" id="apGoalStatus"><option value="">All statuses</option>${['PENDING_APPROVAL','ACTIVE','AT_RISK','COMPLETED','CANCELLED'].map(value=>`<option>${value}</option>`).join('')}</select></label><label>Category<select class="ap-select" id="apGoalCategory"><option value="">All categories</option>${['PERFORMANCE','DEVELOPMENT','EDUCATION','LEADERSHIP','QUALITY','SAFETY','ATTENDANCE','OTHER'].map(value=>`<option>${value}</option>`).join('')}</select></label></div><div id="apGoalList"></div>`}
  function renderGoalList(){const box=document.getElementById('apGoalList');if(!box)return;const q=String(document.getElementById('apGoalSearch')?.value||'').toLowerCase();const status=document.getElementById('apGoalStatus')?.value||'';const category=document.getElementById('apGoalCategory')?.value||'';const rows=state.goals.filter(row=>{const employee=state.team.find(item=>item.id===row.employeeId);return(!q||[employee?.displayName,row.title,row.description].some(value=>String(value||'').toLowerCase().includes(q)))&&(!status||row.status===status)&&(!category||row.category===category)});box.innerHTML=rows.length?`<div class="ap-list">${rows.map(goalRow).join('')}</div>`:'<div class="ap-empty">No goals match these filters.</div>';wireCommon(box)}

  function developmentView(){return `<div class="ap-actions" style="margin-bottom:13px"><button class="ap-btn primary" id="apCreateDevelopment">Create Development Plan</button></div>${state.developmentPlans.length?`<div class="ap-grid three">${state.developmentPlans.map(plan=>{const employee=state.team.find(item=>item.id===plan.employeeId);return `<div class="ap-card ap-dev"><h3>${esc(plan.title)}</h3><div class="ap-sub">${esc(employee?.displayName||plan.employeeId)} · Target ${date(plan.targetDate)}</div><span class="ap-badge ${statusClass(plan.status)}">${label(plan.status)}</span><p style="white-space:pre-wrap">${esc(plan.purpose)}</p><div class="ap-sub">${(plan.actions||[]).length} development action(s) · ${plan.employeeVisible?'Employee visible':'Management only'}</div><div class="ap-form-actions"><button class="ap-btn" data-employee="${esc(plan.employeeId)}">Open Employee</button></div></div>`}).join('')}</div>`:'<div class="ap-empty">No development plans have been created.</div>'}`}

  function actionView(){return `<div class="ap-alert danger"><strong>Restricted HR workflow:</strong> Formal warnings and performance improvement plans are limited to the Enterprise Owner, Human Resources, and Administrators. Every creation, checkpoint, acknowledgment, and resolution is audited.</div><div class="ap-actions" style="margin-bottom:13px">${state.permissions.canManageActionPlans&&!state.permissions.readOnly?'<button class="ap-btn danger" id="apCreateActionPlan">Create Formal Action Plan</button>':''}</div>${state.actionPlans.length?`<div class="ap-grid three">${state.actionPlans.map(plan=>{const employee=state.team.find(item=>item.id===plan.employeeId);return `<div class="ap-card ap-pip"><h3>${esc(plan.title)}</h3><div class="ap-sub">${esc(employee?.displayName||plan.employeeId)} · ${date(plan.startDate)} – ${date(plan.endDate)}</div><span class="ap-badge ${statusClass(plan.status)}">${label(plan.status)}</span><span class="ap-badge ${statusClass(plan.severity)}">${label(plan.severity)}</span><p style="white-space:pre-wrap">${esc(plan.reason)}</p><div class="ap-sub">Visibility: ${label(plan.confidentiality)} · Acknowledged ${date(plan.acknowledgedAt)}</div><div class="ap-form-actions"><button class="ap-btn" data-employee="${esc(plan.employeeId)}">Open Employee</button></div></div>`}).join('')}</div>`:'<div class="ap-empty">No formal performance action plans are in your authorized scope.</div>'}`}

  function cyclesView(){return `<div class="ap-actions" style="margin-bottom:13px">${state.permissions.canManageConfiguration&&!state.permissions.readOnly?'<button class="ap-btn primary" id="apCreateCycle">Create Review Cycle</button>':''}</div>${state.cycles.length?`<div class="ap-list">${state.cycles.map(cycle=>`<div class="ap-row"><div><div class="ap-title">${esc(cycle.name)}</div><div class="ap-sub">${date(cycle.periodStart)} – ${date(cycle.periodEnd)} · Self due ${dateTime(cycle.selfAssessmentDueAt)} · Manager due ${dateTime(cycle.managerAssessmentDueAt)}</div><span class="ap-badge ${statusClass(cycle.status)}">${label(cycle.status)}</span></div><div class="ap-row-actions">${state.permissions.canManageConfiguration&&!state.permissions.readOnly?`<button class="ap-btn" data-edit-cycle="${esc(cycle.id)}">Edit</button>${cycle.status!=='CLOSED'&&cycle.status!=='ARCHIVED'?`<button class="ap-btn primary" data-launch-cycle="${esc(cycle.id)}">Launch / Add Eligible Employees</button><button class="ap-btn danger" data-close-cycle="${esc(cycle.id)}">Close</button>`:''}`:''}</div></div>`).join('')}</div>`:'<div class="ap-empty">No performance review cycles have been created.</div>'}`}

  function templatesView(){return `<div class="ap-actions" style="margin-bottom:13px">${state.permissions.canManageConfiguration&&!state.permissions.readOnly?'<button class="ap-btn primary" id="apCreateTemplate">Create Template</button>':''}</div><div class="ap-grid">${state.templates.map(template=>`<div class="ap-card"><h3>${esc(template.name)}</h3><p>${esc(template.description||'')}</p><div class="ap-sub">Goals ${number(template.goalWeight)}% · Competencies ${number(template.competencyWeight)}% · ${template.competencies.length} competencies · ${template.active?'Active':'Inactive'}</div><div>${template.competencies.map(item=>`<span class="ap-badge">${esc(item.name)} ${number(item.weight)}%</span>`).join('')}</div>${state.permissions.canManageConfiguration&&!state.permissions.readOnly?`<div class="ap-form-actions"><button class="ap-btn" data-edit-template="${esc(template.id)}">Edit Template</button></div>`:''}</div>`).join('')}</div>`}

  function wireCommon(root=document){root.querySelectorAll('[data-review]').forEach(button=>button.onclick=()=>openReview(button.dataset.review));root.querySelectorAll('[data-employee]').forEach(button=>button.onclick=()=>openEmployee(button.dataset.employee));root.querySelectorAll('[data-edit-goal]').forEach(button=>button.onclick=()=>goalForm(state.goals.find(row=>row.id===button.dataset.editGoal)));}
  function wire(){wireCommon();if(activeTab==='reviews'){['apReviewSearch','apReviewStatus','apReviewCycle'].forEach(id=>document.getElementById(id)?.addEventListener(id==='apReviewSearch'?'input':'change',renderReviewList));renderReviewList()}if(activeTab==='team'){document.getElementById('apTeamSearch')?.addEventListener('input',renderTeam);document.getElementById('apTeamRisk')?.addEventListener('change',renderTeam);renderTeam()}if(activeTab==='goals'){document.getElementById('apCreateGoal')?.addEventListener('click',()=>goalForm());['apGoalSearch','apGoalStatus','apGoalCategory'].forEach(id=>document.getElementById(id)?.addEventListener(id==='apGoalSearch'?'input':'change',renderGoalList));renderGoalList()}document.getElementById('apCreateDevelopment')?.addEventListener('click',()=>developmentForm());document.getElementById('apCreateActionPlan')?.addEventListener('click',()=>actionPlanForm());document.getElementById('apCreateCycle')?.addEventListener('click',()=>cycleForm());document.querySelectorAll('[data-edit-cycle]').forEach(button=>button.onclick=()=>cycleForm(state.cycles.find(row=>row.id===button.dataset.editCycle)));document.querySelectorAll('[data-launch-cycle]').forEach(button=>button.onclick=()=>launchCycle(button.dataset.launchCycle));document.querySelectorAll('[data-close-cycle]').forEach(button=>button.onclick=()=>closeCycle(button.dataset.closeCycle));document.getElementById('apCreateTemplate')?.addEventListener('click',()=>templateForm());document.querySelectorAll('[data-edit-template]').forEach(button=>button.onclick=()=>templateForm(state.templates.find(row=>row.id===button.dataset.editTemplate)))}

  async function openEmployee(id){selectedEmployeeId=id;try{const data=await api(`/api/admin/employees/${encodeURIComponent(id)}/performance`);const p=state.permissions;openModal(`${data.employee.displayName} — Performance`,`${!p.readOnly?`<div class="ap-actions"><button class="ap-btn primary" id="apEmployeeGoal">Assign Goal</button><button class="ap-btn" id="apEmployeeDevelopment">Create Development Plan</button>${p.canManageActionPlans?'<button class="ap-btn danger" id="apEmployeeActionPlan">Create Action Plan</button>':''}</div>`:''}<div class="ap-metrics" style="margin-top:14px">${metric('Reviews',data.reviews.length,'Performance-review history')}${metric('Goals',data.goals.length,'All goals in authorized visibility')}${metric('Development Plans',data.developmentPlans.length,'Growth plans')}${metric('Action Plans',data.actionPlans.length,'Formal plans')}${metric('Events',data.events.length,'Performance audit events')}</div><div class="ap-section"><h3>Reviews</h3><div class="ap-list">${data.reviews.map(reviewRow).join('')||'<div class="ap-row">No reviews.</div>'}</div></div><div class="ap-section"><h3>Goals</h3><div class="ap-list">${data.goals.map(goalRow).join('')||'<div class="ap-row">No goals.</div>'}</div></div><div class="ap-section"><h3>Development Plans</h3><div class="ap-grid">${data.developmentPlans.map(plan=>`<div class="ap-card ap-dev"><h3>${esc(plan.title)}</h3><span class="ap-badge ${statusClass(plan.status)}">${label(plan.status)}</span><p style="white-space:pre-wrap">${esc(plan.purpose)}</p><div class="ap-list">${(plan.actions||[]).map(action=>`<div class="ap-row"><div><div class="ap-title">${esc(action.title)}</div><div class="ap-sub">${label(action.owner)} · Due ${date(action.dueDate)}${action.courseCode?` · Course ${esc(action.courseCode)}`:''}</div></div><span class="ap-badge ${statusClass(action.status)}">${label(action.status)}</span></div>`).join('')}</div>${!p.readOnly?`<div class="ap-form-actions"><button class="ap-btn" data-edit-development="${esc(plan.id)}">Edit Plan</button></div>`:''}</div>`).join('')||'<div class="ap-empty">No development plans.</div>'}</div></div><div class="ap-section"><h3>Formal Action Plans</h3><div class="ap-grid">${data.actionPlans.map(plan=>`<div class="ap-card ap-pip"><h3>${esc(plan.title)}</h3><span class="ap-badge ${statusClass(plan.status)}">${label(plan.status)}</span><span class="ap-badge">${label(plan.severity)}</span><p><strong>Reason:</strong><br>${esc(plan.reason)}</p><p><strong>Expectations:</strong><br>${esc(plan.expectations)}</p><div class="ap-sub">${date(plan.startDate)} – ${date(plan.endDate)} · ${label(plan.confidentiality)} · Acknowledged ${date(plan.acknowledgedAt)}</div>${p.canManageActionPlans&&!p.readOnly?`<div class="ap-form-actions"><button class="ap-btn" data-checkpoint="${esc(plan.id)}">Record Checkpoint</button><button class="ap-btn danger" data-resolve-plan="${esc(plan.id)}">Change Status</button></div>`:''}</div>`).join('')||'<div class="ap-empty">No action plans.</div>'}</div></div><div class="ap-section"><h3>Performance Audit Timeline</h3><div class="ap-timeline">${data.events.map(item=>`<div class="ap-step"><strong>${label(item.eventType)}</strong><div class="ap-sub">${dateTime(item.createdAt)} · ${label(item.resourceType)}</div></div>`).join('')}</div></div>`);document.getElementById('apEmployeeGoal')?.addEventListener('click',()=>goalForm(null,id));document.getElementById('apEmployeeDevelopment')?.addEventListener('click',()=>developmentForm(id));document.getElementById('apEmployeeActionPlan')?.addEventListener('click',()=>actionPlanForm(id));document.querySelectorAll('#apModalBody [data-review]').forEach(button=>button.onclick=()=>openReview(button.dataset.review));document.querySelectorAll('#apModalBody [data-edit-goal]').forEach(button=>button.onclick=()=>goalForm(data.goals.find(row=>row.id===button.dataset.editGoal)));document.querySelectorAll('[data-edit-development]').forEach(button=>button.onclick=()=>developmentForm(id,data.developmentPlans.find(row=>row.id===button.dataset.editDevelopment)));document.querySelectorAll('[data-checkpoint]').forEach(button=>button.onclick=()=>checkpointForm(button.dataset.checkpoint,id));document.querySelectorAll('[data-resolve-plan]').forEach(button=>button.onclick=()=>resolvePlanForm(button.dataset.resolvePlan,id))}catch(error){setStatus(error.message,true)}}

  async function openReview(id){try{selectedReview=await api(`/api/admin/employee-performance/reviews/${encodeURIComponent(id)}`);const {review,cycle,employee,manager,assessments,goals,events}=selectedReview;const employeeAssessment=assessments.find(item=>item.assessorType==='EMPLOYEE');const managerAssessment=assessments.find(item=>item.assessorType==='MANAGER');const canAssess=state.permissions.canAssess&&!state.permissions.readOnly&&['EMPLOYEE_INPUT','MANAGER_REVIEW'].includes(review.status);const canCalibrate=state.permissions.canCalibrate&&!state.permissions.readOnly&&['MANAGER_REVIEW','CALIBRATION'].includes(review.status);openModal(`${employee.displayName} — ${cycle.name}`,`<div class="ap-grid three"><div class="ap-card"><h4>Status</h4><span class="ap-badge ${statusClass(review.status)}">${label(review.status)}</span></div><div class="ap-card"><h4>Manager</h4><strong>${esc(manager?.displayName||'Not assigned')}</strong></div><div class="ap-card"><h4>Period</h4><strong>${date(cycle.periodStart)} – ${date(cycle.periodEnd)}</strong></div><div class="ap-card"><h4>Final Rating</h4><div class="ap-metric">${number(review.finalRating)}</div></div><div class="ap-card"><h4>Final Score</h4><div class="ap-metric">${number(review.finalScore)}</div></div><div class="ap-card"><h4>Employee Acknowledgment</h4><strong>${dateTime(review.acknowledgedAt)}</strong></div></div><div class="ap-actions" style="margin-top:14px"><button class="ap-btn" id="apReviewReport">Print / Save PDF</button>${canCalibrate?'<button class="ap-btn warn" id="apCalibrateReview">Calibrate Rating</button>':''}${!state.permissions.readOnly&&['MANAGER_REVIEW','CALIBRATION'].includes(review.status)?'<button class="ap-btn success" id="apFinalizeReview">Finalize Review</button>':''}</div><div class="ap-section"><h3>Goals</h3><div class="ap-list">${goals.map(goalRow).join('')||'<div class="ap-row">No goals assigned to this review.</div>'}</div></div>${employeeAssessment?`<div class="ap-section"><h3>Employee Self-Assessment</h3><div class="ap-card"><div class="ap-sub">Submitted ${dateTime(employeeAssessment.submittedAt)} · Competency score ${number(employeeAssessment.competencyScore)} · Goal score ${number(employeeAssessment.goalScore)}</div><pre style="white-space:pre-wrap;overflow:auto">${esc(JSON.stringify(employeeAssessment.responses,null,2))}</pre></div></div>`:''}${canAssess?managerAssessmentForm(cycle,goals,managerAssessment?.responses||{}):managerAssessment?`<div class="ap-section"><h3>Manager Assessment</h3><div class="ap-card"><div class="ap-sub">Submitted ${dateTime(managerAssessment.submittedAt)} · Competency score ${number(managerAssessment.competencyScore)} · Goal score ${number(managerAssessment.goalScore)}</div><pre style="white-space:pre-wrap;overflow:auto">${esc(JSON.stringify(managerAssessment.responses,null,2))}</pre></div></div>`:''}<div class="ap-section"><h3>Final Summary</h3><div class="ap-card"><h4>Summary</h4><p style="white-space:pre-wrap">${esc(review.summary||'—')}</p><h4>Strengths</h4><p style="white-space:pre-wrap">${esc(review.strengths||'—')}</p><h4>Improvement Areas</h4><p style="white-space:pre-wrap">${esc(review.improvementAreas||'—')}</p></div></div><div class="ap-section"><h3>Audit Timeline</h3><div class="ap-timeline">${events.map(item=>`<div class="ap-step"><strong>${label(item.eventType)}</strong><div class="ap-sub">${dateTime(item.createdAt)}</div></div>`).join('')}</div></div>`);document.getElementById('apManagerAssessmentForm')?.addEventListener('submit',submitManagerAssessment);document.getElementById('apCalibrateReview')?.addEventListener('click',calibrateReview);document.getElementById('apFinalizeReview')?.addEventListener('click',finalizeReview);document.getElementById('apReviewReport')?.addEventListener('click',()=>printReview(review.id));document.querySelectorAll('#apModalBody [data-edit-goal]').forEach(button=>button.onclick=()=>goalForm(goals.find(row=>row.id===button.dataset.editGoal)))}catch(error){setStatus(error.message,true)}}

  function managerAssessmentForm(cycle,goals,existing){const priorComp=new Map((existing.competencyRatings||[]).map(item=>[item.competencyId,item]));const priorGoals=new Map((existing.goalRatings||[]).map(item=>[item.goalId,item]));const options=(cycle.ratingScale||[]).map(item=>`<option value="${Number(item.value)}">${Number(item.value)} — ${esc(item.label)}</option>`).join('');return `<div class="ap-section"><h3>Manager Assessment</h3><div class="ap-alert">Use specific, job-related examples. Ratings and comments become part of the permanent Employee 360 performance record after finalization.</div><form id="apManagerAssessmentForm" class="ap-form"><h4>Competencies</h4><div class="ap-list">${(cycle.competencies||[]).map(item=>{const prior=priorComp.get(item.id)||{};return `<div class="ap-rating-row" data-manager-competency="${esc(item.id)}"><div><strong>${esc(item.name)}</strong><div class="ap-sub">${esc(item.description||'')} · Weight ${number(item.weight)}%</div></div><select class="ap-select" data-field="rating" required><option value="">Rating</option>${options.replace(`value="${prior.rating}"`,`value="${prior.rating}" selected`)}</select><textarea class="ap-textarea" data-field="comments" placeholder="Evidence and examples">${esc(prior.comments||'')}</textarea></div>`}).join('')}</div>${goals.length?`<h4 style="margin-top:14px">Goals</h4><div class="ap-list">${goals.map(goal=>{const prior=priorGoals.get(goal.id)||{};return `<div class="ap-rating-row" data-manager-goal="${esc(goal.id)}"><div><strong>${esc(goal.title)}</strong><div class="ap-sub">${number(goal.progressPercent)}% progress · Weight ${number(goal.weight)}%</div></div><select class="ap-select" data-field="rating" required><option value="">Rating</option>${options.replace(`value="${prior.rating}"`,`value="${prior.rating}" selected`)}</select><textarea class="ap-textarea" data-field="comments" placeholder="Results and evidence">${esc(prior.comments||'')}</textarea></div>`}).join('')}</div>`:''}<div class="ap-grid" style="margin-top:14px"><label>Summary<textarea class="ap-textarea" name="summary">${esc(existing.summary||'')}</textarea></label><label>Strengths<textarea class="ap-textarea" name="strengths">${esc(existing.strengths||'')}</textarea></label><label>Improvement areas<textarea class="ap-textarea" name="improvementAreas">${esc(existing.improvementAreas||'')}</textarea></label><label>Overall manager comments<textarea class="ap-textarea" name="overallComments">${esc(existing.overallComments||'')}</textarea></label><label>Accomplishments<textarea class="ap-textarea" name="accomplishments">${esc(existing.accomplishments||'')}</textarea></label><label>Challenges and support needed<textarea class="ap-textarea" name="challenges">${esc(existing.challenges||'')}</textarea></label><label>Recommended overall rating<input class="ap-input" type="number" min="1" max="10" step="0.01" name="recommendedRating" value="${existing.recommendedRating??''}"></label></div><div class="ap-form-actions"><button class="ap-btn primary" type="submit">Submit Manager Assessment</button></div></form></div>`}

  async function submitManagerAssessment(event){event.preventDefault();if(!confirm('Submit the manager assessment for calibration and finalization?'))return;const form=event.currentTarget;const competencyRatings=[...form.querySelectorAll('[data-manager-competency]')].map(row=>({competencyId:row.dataset.managerCompetency,rating:Number(row.querySelector('[data-field="rating"]').value),comments:row.querySelector('[data-field="comments"]').value.trim()}));const goalRatings=[...form.querySelectorAll('[data-manager-goal]')].map(row=>({goalId:row.dataset.managerGoal,rating:Number(row.querySelector('[data-field="rating"]').value),comments:row.querySelector('[data-field="comments"]').value.trim()}));const data=new FormData(form);try{await api(`/api/admin/employee-performance/reviews/${encodeURIComponent(selectedReview.review.id)}/manager-assessment`,{method:'POST',body:JSON.stringify({competencyRatings,goalRatings,summary:String(data.get('summary')||''),strengths:String(data.get('strengths')||''),improvementAreas:String(data.get('improvementAreas')||''),overallComments:String(data.get('overallComments')||''),accomplishments:String(data.get('accomplishments')||''),challenges:String(data.get('challenges')||''),supportNeeded:'',recommendedRating:data.get('recommendedRating')===''?null:Number(data.get('recommendedRating'))})});await load();await openReview(selectedReview.review.id);setStatus('Manager assessment submitted.')}catch(error){alert(error.message)}}
  async function calibrateReview(){const rating=prompt('Calibrated final rating (1–10):',String(selectedReview.review.calibrationRating||selectedReview.review.finalRating||3));if(rating===null)return;const notes=prompt('Calibration notes and business rationale:','Calibration review completed.')??null;if(notes===null)return;try{await api(`/api/admin/employee-performance/reviews/${encodeURIComponent(selectedReview.review.id)}/calibrate`,{method:'POST',body:JSON.stringify({calibrationRating:Number(rating),notes})});await load();await openReview(selectedReview.review.id);setStatus('Performance rating calibrated.')}catch(error){alert(error.message)}}
  async function finalizeReview(){if(!confirm('Finalize this performance review? The employee will be notified and acknowledgment may be required.'))return;try{await api(`/api/admin/employee-performance/reviews/${encodeURIComponent(selectedReview.review.id)}/finalize`,{method:'POST'});await load();await openReview(selectedReview.review.id);setStatus('Performance review finalized and employee notification created.')}catch(error){alert(error.message)}}
  async function printReview(id){try{const response=await api(`/api/admin/employee-performance/reviews/${encodeURIComponent(id)}/report`,{raw:true,accept:'text/html'});const html=await response.text();const win=window.open('','_blank');if(!win)throw new Error('Allow pop-ups to open the printable review report.');win.document.open();win.document.write(html);win.document.close()}catch(error){alert(error.message)}}

  function employeeOptions(selected=''){return state.team.map(employee=>`<option value="${esc(employee.id)}" ${employee.id===selected?'selected':''}>${esc(employee.displayName)} — ${esc(employee.jobTitle||label(employee.role))}</option>`).join('')}
  function goalForm(goal=null,employeeId=''){const selectedEmployee=employeeId||goal?.employeeId||state.team[0]?.id||'';openModal(goal?'Edit Goal':'Assign Performance or Development Goal',`<form id="apGoalForm" class="ap-form"><div class="ap-grid three"><label>Employee<select class="ap-select" name="employeeId" ${goal?'disabled':''}>${employeeOptions(selectedEmployee)}</select></label><label>Category<select class="ap-select" name="category">${['PERFORMANCE','DEVELOPMENT','COMPLIANCE','EDUCATION','LEADERSHIP','QUALITY','SAFETY','ATTENDANCE','OTHER'].map(value=>`<option ${goal?.category===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Status<select class="ap-select" name="status">${['PENDING_APPROVAL','ACTIVE','AT_RISK','COMPLETED','CANCELLED'].map(value=>`<option ${goal?.status===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Metric type<select class="ap-select" name="metricType">${['PERCENT','NUMBER','CURRENCY','MILESTONE','BOOLEAN'].map(value=>`<option ${goal?.metricType===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Target value<input class="ap-input" type="number" step="0.01" name="targetValue" value="${goal?.targetValue??''}"></label><label>Current value<input class="ap-input" type="number" step="0.01" name="currentValue" value="${goal?.currentValue??''}"></label><label>Unit<input class="ap-input" name="unit" value="${esc(goal?.unit||'')}"></label><label>Start date<input class="ap-input" type="date" name="startDate" value="${toInputDate(goal?.startDate)}"></label><label>Due date<input class="ap-input" type="date" name="dueDate" value="${toInputDate(goal?.dueDate)}"></label><label>Weight<input class="ap-input" type="number" min="0" max="100" name="weight" value="${Number(goal?.weight||0)}"></label><label>Visibility<select class="ap-select" name="visibility"><option ${goal?.visibility==='EMPLOYEE_VISIBLE'?'selected':''}>EMPLOYEE_VISIBLE</option><option ${goal?.visibility==='MANAGEMENT_ONLY'?'selected':''}>MANAGEMENT_ONLY</option>${state.permissions.canManageActionPlans?`<option ${goal?.visibility==='HR_CONFIDENTIAL'?'selected':''}>HR_CONFIDENTIAL</option>`:''}</select></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="employeeCanUpdate" style="width:auto" ${goal?.employeeCanUpdate!==false?'checked':''}> Employee can update progress</label></div><label style="display:block;margin-top:10px">Goal title<input class="ap-input" name="title" value="${esc(goal?.title||'')}" required></label><label style="display:block;margin-top:10px">Description and success criteria<textarea class="ap-textarea" name="description" required>${esc(goal?.description||'')}</textarea></label><div class="ap-form-actions"><button class="ap-btn primary" type="submit">${goal?'Save Goal':'Assign Goal'}</button></div></form>`);document.getElementById('apGoalForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget);const body={title:String(data.get('title')||'').trim(),description:String(data.get('description')||'').trim(),category:String(data.get('category')),status:String(data.get('status')),metricType:String(data.get('metricType')),targetValue:data.get('targetValue')===''?null:Number(data.get('targetValue')),currentValue:data.get('currentValue')===''?null:Number(data.get('currentValue')),unit:String(data.get('unit')||''),startDate:data.get('startDate')||null,dueDate:data.get('dueDate')||null,weight:Number(data.get('weight')||0),visibility:String(data.get('visibility')),employeeCanUpdate:data.get('employeeCanUpdate')==='on'};try{if(goal)await api(`/api/admin/employee-performance/goals/${encodeURIComponent(goal.id)}`,{method:'PATCH',body:JSON.stringify(body)});else await api(`/api/admin/employees/${encodeURIComponent(String(data.get('employeeId')))}/performance/goals`,{method:'POST',body:JSON.stringify(body)});closeModal();await load();setStatus(goal?'Goal updated.':'Goal assigned and employee notification created when visible.')}catch(error){alert(error.message)}}}

  function developmentForm(employeeId='',plan=null){const selected=employeeId||plan?.employeeId||state.team[0]?.id||'';const actions=plan?.actions?.length?plan.actions:[{id:crypto.randomUUID(),title:'',description:'',owner:'EMPLOYEE',dueDate:null,status:'NOT_STARTED',courseCode:null,evidenceUrl:null}];openModal(plan?'Edit Development Plan':'Create Employee Development Plan',`<form id="apDevelopmentForm" class="ap-form"><div class="ap-grid three"><label>Employee<select class="ap-select" name="employeeId" ${plan?'disabled':''}>${employeeOptions(selected)}</select></label><label>Start date<input class="ap-input" type="date" name="startDate" value="${toInputDate(plan?.startDate)}"></label><label>Target date<input class="ap-input" type="date" name="targetDate" value="${toInputDate(plan?.targetDate)}"></label><label>Status<select class="ap-select" name="status">${['DRAFT','ACTIVE','COMPLETED','CANCELLED'].map(value=>`<option ${plan?.status===value?'selected':''}>${value}</option>`).join('')}</select></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="employeeVisible" style="width:auto" ${plan?.employeeVisible!==false?'checked':''}> Employee visible</label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="acknowledgmentRequired" style="width:auto" ${plan?.acknowledgmentRequired!==false?'checked':''}> Acknowledgment required</label></div><label style="display:block;margin-top:10px">Plan title<input class="ap-input" name="title" value="${esc(plan?.title||'')}" required></label><label style="display:block;margin-top:10px">Purpose and expected development outcome<textarea class="ap-textarea" name="purpose" required>${esc(plan?.purpose||'')}</textarea></label><div class="ap-section"><h3>Development Actions</h3><div id="apDevelopmentActions">${actions.map(developmentActionRow).join('')}</div><div class="ap-form-actions"><button class="ap-btn" type="button" id="apAddDevelopmentAction">Add Action</button></div></div><div class="ap-form-actions"><button class="ap-btn primary" type="submit">${plan?'Save Development Plan':'Create Development Plan'}</button></div></form>`);const rerender=()=>{document.getElementById('apDevelopmentActions').innerHTML=actions.map(developmentActionRow).join('');document.querySelectorAll('[data-remove-dev-action]').forEach(button=>button.onclick=()=>{syncDevelopmentActions(actions);actions.splice(Number(button.dataset.removeDevAction),1);rerender()})};document.getElementById('apAddDevelopmentAction').onclick=()=>{syncDevelopmentActions(actions);actions.push({id:crypto.randomUUID(),title:'',description:'',owner:'EMPLOYEE',dueDate:null,status:'NOT_STARTED',courseCode:null,evidenceUrl:null});rerender()};rerender();document.getElementById('apDevelopmentForm').onsubmit=async event=>{event.preventDefault();syncDevelopmentActions(actions);const data=new FormData(event.currentTarget);const body={title:String(data.get('title')||'').trim(),purpose:String(data.get('purpose')||'').trim(),startDate:data.get('startDate')||null,targetDate:data.get('targetDate')||null,status:String(data.get('status')),employeeVisible:data.get('employeeVisible')==='on',acknowledgmentRequired:data.get('acknowledgmentRequired')==='on',actions};try{if(plan)await api(`/api/admin/employee-performance/development-plans/${encodeURIComponent(plan.id)}`,{method:'PATCH',body:JSON.stringify(body)});else await api(`/api/admin/employees/${encodeURIComponent(String(data.get('employeeId')))}/performance/development-plans`,{method:'POST',body:JSON.stringify(body)});closeModal();await load();setStatus(plan?'Development plan updated.':'Development plan created and employee notified when visible.')}catch(error){alert(error.message)}}}
  function developmentActionRow(action,index){return `<div class="ap-template-competency" data-dev-action="${index}"><label>Owner<select class="ap-select" data-field="owner">${['EMPLOYEE','MANAGER','HR','SHARED'].map(value=>`<option ${action.owner===value?'selected':''}>${value}</option>`).join('')}</select></label><label>Action title<input class="ap-input" data-field="title" value="${esc(action.title||'')}"></label><label>Due date<input class="ap-input" type="date" data-field="dueDate" value="${toInputDate(action.dueDate)}"></label><label>Description / course code<input class="ap-input" data-field="description" value="${esc(action.description||'')}" placeholder="Description"><input class="ap-input" style="margin-top:5px" data-field="courseCode" value="${esc(action.courseCode||'')}" placeholder="Optional course code"></label><button class="ap-btn danger" type="button" data-remove-dev-action="${index}">Remove</button></div>`}
  function syncDevelopmentActions(actions){document.querySelectorAll('[data-dev-action]').forEach(row=>{const index=Number(row.dataset.devAction);actions[index]={...actions[index],owner:row.querySelector('[data-field="owner"]').value,title:row.querySelector('[data-field="title"]').value.trim(),dueDate:row.querySelector('[data-field="dueDate"]').value||null,description:row.querySelector('[data-field="description"]').value.trim(),courseCode:row.querySelector('[data-field="courseCode"]').value.trim()||null}})}

  function actionPlanForm(employeeId=''){const selected=employeeId||state.team[0]?.id||'';openModal('Create Formal Performance Action Plan',`<form id="apActionPlanForm" class="ap-form"><div class="ap-alert danger"><strong>HR-controlled record:</strong> Use objective, job-related facts. Confirm policy, legal, and Human Resources review before finalizing disciplinary action.</div><div class="ap-grid three"><label>Employee<select class="ap-select" name="employeeId">${employeeOptions(selected)}</select></label><label>Severity<select class="ap-select" name="severity"><option>COACHING</option><option>FORMAL_WARNING</option><option selected>PERFORMANCE_IMPROVEMENT_PLAN</option><option>FINAL_WARNING</option></select></label><label>Status<select class="ap-select" name="status"><option>DRAFT</option><option selected>ACTIVE</option></select></label><label>Start date<input class="ap-input" type="date" name="startDate" value="${new Date().toISOString().slice(0,10)}" required></label><label>End date<input class="ap-input" type="date" name="endDate" required></label><label>Confidentiality<select class="ap-select" name="confidentiality"><option>EMPLOYEE_VISIBLE</option><option>MANAGEMENT_ONLY</option><option>HR_CONFIDENTIAL</option></select></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="employeeVisible" style="width:auto" checked> Employee-visible when confidentiality allows</label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="acknowledgmentRequired" style="width:auto" checked> Employee acknowledgment required</label></div><label style="display:block;margin-top:10px">Plan title<input class="ap-input" name="title" required></label><label style="display:block;margin-top:10px">Documented reason and performance gap<textarea class="ap-textarea" name="reason" required></textarea></label><label style="display:block;margin-top:10px">Measurable expectations<textarea class="ap-textarea" name="expectations" required></textarea></label><label style="display:block;margin-top:10px">Support, training, resources, and supervision provided<textarea class="ap-textarea" name="supportProvided"></textarea></label><div class="ap-form-actions"><button class="ap-btn danger" type="submit">Create Formal Action Plan</button></div></form>`);document.getElementById('apActionPlanForm').onsubmit=async event=>{event.preventDefault();if(!confirm('Create this formal performance action plan? This action is audited and may notify the employee.'))return;const data=new FormData(event.currentTarget);try{await api(`/api/admin/employees/${encodeURIComponent(String(data.get('employeeId')))}/performance/action-plans`,{method:'POST',body:JSON.stringify({title:String(data.get('title')||'').trim(),reason:String(data.get('reason')||'').trim(),expectations:String(data.get('expectations')||'').trim(),supportProvided:String(data.get('supportProvided')||'').trim(),startDate:String(data.get('startDate')),endDate:String(data.get('endDate')),severity:String(data.get('severity')),status:String(data.get('status')),employeeVisible:data.get('employeeVisible')==='on',acknowledgmentRequired:data.get('acknowledgmentRequired')==='on',confidentiality:String(data.get('confidentiality'))})});closeModal();await load();setStatus('Formal performance action plan created.')}catch(error){alert(error.message)}}}
  function checkpointForm(planId,employeeId){openModal('Record Action Plan Checkpoint',`<form id="apCheckpointForm" class="ap-form"><div class="ap-grid three"><label>Scheduled date<input class="ap-input" type="date" name="scheduledDate" value="${new Date().toISOString().slice(0,10)}" required></label><label>Completed date<input class="ap-input" type="date" name="completedDate"></label><label>Status<select class="ap-select" name="status"><option>SCHEDULED</option><option>COMPLETED</option><option>MISSED</option><option>RESCHEDULED</option></select></label><label>Outcome<select class="ap-select" name="outcome"><option>PENDING</option><option>ON_TRACK</option><option>NEEDS_IMPROVEMENT</option><option>MET</option><option>NOT_MET</option></select></label></div><label style="display:block;margin-top:10px">Employee progress<textarea class="ap-textarea" name="employeeProgress"></textarea></label><label style="display:block;margin-top:10px">Manager assessment<textarea class="ap-textarea" name="managerAssessment"></textarea></label><label style="display:block;margin-top:10px">Next steps<textarea class="ap-textarea" name="nextSteps"></textarea></label><div class="ap-form-actions"><button class="ap-btn primary" type="submit">Save Checkpoint</button></div></form>`);document.getElementById('apCheckpointForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget);try{await api(`/api/admin/employee-performance/action-plans/${encodeURIComponent(planId)}/checkpoints`,{method:'POST',body:JSON.stringify({scheduledDate:String(data.get('scheduledDate')),completedDate:data.get('completedDate')||null,status:String(data.get('status')),outcome:String(data.get('outcome')),employeeProgress:String(data.get('employeeProgress')||''),managerAssessment:String(data.get('managerAssessment')||''),nextSteps:String(data.get('nextSteps')||'')})});await openEmployee(employeeId);await load()}catch(error){alert(error.message)}}}
  function resolvePlanForm(planId,employeeId){openModal('Change Action Plan Status',`<form id="apResolvePlanForm" class="ap-form"><label>Status<select class="ap-select" name="status"><option>ACTIVE</option><option>EXTENDED</option><option>SUCCESSFULLY_COMPLETED</option><option>UNSUCCESSFUL</option><option>CANCELLED</option></select></label><label style="display:block;margin-top:10px">Revised end date<input class="ap-input" type="date" name="endDate"></label><label style="display:block;margin-top:10px">Resolution notes<textarea class="ap-textarea" name="resolutionNotes" required></textarea></label><div class="ap-form-actions"><button class="ap-btn danger" type="submit">Update Formal Plan</button></div></form>`,false);document.getElementById('apResolvePlanForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget);if(!confirm('Update this formal plan status? This decision is audited.'))return;try{await api(`/api/admin/employee-performance/action-plans/${encodeURIComponent(planId)}/status`,{method:'PATCH',body:JSON.stringify({status:String(data.get('status')),endDate:data.get('endDate')||null,resolutionNotes:String(data.get('resolutionNotes')||'').trim()})});await openEmployee(employeeId);await load()}catch(error){alert(error.message)}}}

  function cycleForm(cycle=null){const template=cycle?.templateId||state.templates.find(item=>item.active)?.id||state.templates[0]?.id||'';const app=cycle?.applicability||{};openModal(cycle?'Edit Review Cycle':'Create Performance Review Cycle',`<form id="apCycleForm" class="ap-form"><div class="ap-grid three"><label>Template<select class="ap-select" name="templateId">${state.templates.filter(item=>item.active||item.id===template).map(item=>`<option value="${esc(item.id)}" ${item.id===template?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><label>Period start<input class="ap-input" type="date" name="periodStart" value="${toInputDate(cycle?.periodStart)}" required></label><label>Period end<input class="ap-input" type="date" name="periodEnd" value="${toInputDate(cycle?.periodEnd)}" required></label><label>Self-assessment due<input class="ap-input" type="datetime-local" name="selfAssessmentDueAt" value="${toInputDateTime(cycle?.selfAssessmentDueAt)}"></label><label>Manager assessment due<input class="ap-input" type="datetime-local" name="managerAssessmentDueAt" value="${toInputDateTime(cycle?.managerAssessmentDueAt)}"></label><label>Acknowledgment due<input class="ap-input" type="datetime-local" name="acknowledgmentDueAt" value="${toInputDateTime(cycle?.acknowledgmentDueAt)}"></label></div><label style="display:block;margin-top:10px">Cycle name<input class="ap-input" name="name" value="${esc(cycle?.name||'')}" required></label><label style="display:block;margin-top:10px">Description<textarea class="ap-textarea" name="description">${esc(cycle?.description||'')}</textarea></label><div class="ap-section"><h3>Applicability</h3><div class="ap-alert">Leave a field blank to include all values. Use comma-separated exact system role, department, job title, service-location ID, or employment-status values.</div><div class="ap-grid"><label>Roles<input class="ap-input" name="roles" value="${esc((app.roles||[]).join(', '))}"></label><label>Departments<input class="ap-input" name="departments" value="${esc((app.departments||[]).join(', '))}"></label><label>Job titles<input class="ap-input" name="jobTitles" value="${esc((app.jobTitles||[]).join(', '))}"></label><label>Service-location IDs<input class="ap-input" name="locationIds" value="${esc((app.locationIds||[]).join(', '))}"></label><label>Employment statuses<input class="ap-input" name="employmentStatuses" value="${esc((app.employmentStatuses||['ACTIVE','ON_LEAVE']).join(', '))}"></label></div></div><div class="ap-form-actions"><button class="ap-btn primary" type="submit">${cycle?'Save Cycle':'Create Draft Cycle'}</button></div></form>`);document.getElementById('apCycleForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget),split=name=>String(data.get(name)||'').split(',').map(value=>value.trim()).filter(Boolean);const body={templateId:String(data.get('templateId')),name:String(data.get('name')||'').trim(),description:String(data.get('description')||''),periodStart:String(data.get('periodStart')),periodEnd:String(data.get('periodEnd')),selfAssessmentDueAt:data.get('selfAssessmentDueAt')||null,managerAssessmentDueAt:data.get('managerAssessmentDueAt')||null,acknowledgmentDueAt:data.get('acknowledgmentDueAt')||null,applicability:{roles:split('roles'),departments:split('departments'),jobTitles:split('jobTitles'),locationIds:split('locationIds'),employmentStatuses:split('employmentStatuses')},status:cycle?.status||'DRAFT'};try{if(cycle)await api(`/api/admin/employee-performance/cycles/${encodeURIComponent(cycle.id)}`,{method:'PATCH',body:JSON.stringify(body)});else await api('/api/admin/employee-performance/cycles',{method:'POST',body:JSON.stringify(body)});closeModal();await load();setStatus(cycle?'Review cycle updated.':'Draft performance review cycle created.')}catch(error){alert(error.message)}}}
  async function launchCycle(id){if(!confirm('Launch this review cycle and create reviews for every currently eligible employee? Running it again later safely adds newly eligible employees without duplicating existing reviews.'))return;try{const result=await api(`/api/admin/employee-performance/cycles/${encodeURIComponent(id)}/launch`,{method:'POST'});await load();setStatus(`Cycle launched: ${result.created} new review(s) created for ${result.eligible} eligible employee(s).`)}catch(error){setStatus(error.message,true)}}
  async function closeCycle(id){let force=false;if(!confirm('Close this performance cycle? All reviews should normally be completed first.'))return;try{await api(`/api/admin/employee-performance/cycles/${encodeURIComponent(id)}/close`,{method:'POST',body:JSON.stringify({force:false})})}catch(error){if(!String(error.message).includes('reviews are still open'))return setStatus(error.message,true);force=confirm(`${error.message}\n\nForce administrative closure anyway?`);if(!force)return;await api(`/api/admin/employee-performance/cycles/${encodeURIComponent(id)}/close`,{method:'POST',body:JSON.stringify({force:true})})}await load();setStatus('Performance cycle closed.')}

  function templateForm(template=null){selectedTemplate=template?JSON.parse(JSON.stringify(template)):{id:null,name:'',description:'',goalWeight:50,competencyWeight:50,employeeSelfAssessment:true,employeeAcknowledgment:true,active:true,competencies:[{id:'quality',name:'Quality and Accuracy',description:'',weight:20}],ratingScale:[{value:1,label:'Does Not Meet Expectations',description:''},{value:2,label:'Needs Improvement',description:''},{value:3,label:'Meets Expectations',description:''},{value:4,label:'Exceeds Expectations',description:''},{value:5,label:'Exceptional',description:''}]};openModal(template?'Edit Performance Template':'Create Performance Template',templateEditor());wireTemplateEditor()}
  function templateEditor(){const t=selectedTemplate;return `<form id="apTemplateForm" class="ap-form"><div class="ap-grid three"><label>Goal weight<input class="ap-input" type="number" min="0" max="100" name="goalWeight" value="${Number(t.goalWeight)}"></label><label>Competency weight<input class="ap-input" type="number" min="0" max="100" name="competencyWeight" value="${Number(t.competencyWeight)}"></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="active" style="width:auto" ${t.active?'checked':''}> Active template</label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="employeeSelfAssessment" style="width:auto" ${t.employeeSelfAssessment?'checked':''}> Employee self-assessment</label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="employeeAcknowledgment" style="width:auto" ${t.employeeAcknowledgment?'checked':''}> Employee acknowledgment</label></div><label style="display:block;margin-top:10px">Template name<input class="ap-input" name="name" value="${esc(t.name)}" required></label><label style="display:block;margin-top:10px">Description<textarea class="ap-textarea" name="description">${esc(t.description||'')}</textarea></label><div class="ap-section"><h3>Competencies</h3><div id="apTemplateCompetencies">${t.competencies.map(competencyEditor).join('')}</div><div class="ap-form-actions"><button class="ap-btn" type="button" id="apAddCompetency">Add Competency</button></div></div><div class="ap-section"><h3>Rating Scale</h3><div id="apTemplateRatings">${t.ratingScale.map(ratingEditor).join('')}</div><div class="ap-form-actions"><button class="ap-btn" type="button" id="apAddRating">Add Rating Level</button></div></div><div class="ap-form-actions"><button class="ap-btn primary" type="submit">Save Template</button></div></form>`}
  function competencyEditor(item,index){return `<div class="ap-template-competency" data-template-competency="${index}"><label>ID<input class="ap-input" data-field="id" value="${esc(item.id)}"></label><label>Name<input class="ap-input" data-field="name" value="${esc(item.name)}"></label><label>Weight<input class="ap-input" type="number" min="0" max="100" data-field="weight" value="${Number(item.weight)}"></label><label>Description<textarea class="ap-textarea" data-field="description">${esc(item.description||'')}</textarea></label><button class="ap-btn danger" type="button" data-remove-competency="${index}">Remove</button></div>`}
  function ratingEditor(item,index){return `<div class="ap-template-competency" data-template-rating="${index}"><label>Value<input class="ap-input" type="number" min="1" max="10" data-field="value" value="${Number(item.value)}"></label><label>Label<input class="ap-input" data-field="label" value="${esc(item.label)}"></label><label></label><label>Description<textarea class="ap-textarea" data-field="description">${esc(item.description||'')}</textarea></label><button class="ap-btn danger" type="button" data-remove-rating="${index}">Remove</button></div>`}
  function syncTemplate(){selectedTemplate.competencies=[...document.querySelectorAll('[data-template-competency]')].map(row=>({id:row.querySelector('[data-field="id"]').value.trim(),name:row.querySelector('[data-field="name"]').value.trim(),weight:Number(row.querySelector('[data-field="weight"]').value),description:row.querySelector('[data-field="description"]').value.trim()}));selectedTemplate.ratingScale=[...document.querySelectorAll('[data-template-rating]')].map(row=>({value:Number(row.querySelector('[data-field="value"]').value),label:row.querySelector('[data-field="label"]').value.trim(),description:row.querySelector('[data-field="description"]').value.trim()}))}
  function wireTemplateEditor(){const rerender=()=>{document.getElementById('apTemplateCompetencies').innerHTML=selectedTemplate.competencies.map(competencyEditor).join('');document.getElementById('apTemplateRatings').innerHTML=selectedTemplate.ratingScale.map(ratingEditor).join('');document.querySelectorAll('[data-remove-competency]').forEach(button=>button.onclick=()=>{syncTemplate();selectedTemplate.competencies.splice(Number(button.dataset.removeCompetency),1);rerender()});document.querySelectorAll('[data-remove-rating]').forEach(button=>button.onclick=()=>{syncTemplate();selectedTemplate.ratingScale.splice(Number(button.dataset.removeRating),1);rerender()})};document.getElementById('apAddCompetency').onclick=()=>{syncTemplate();selectedTemplate.competencies.push({id:`competency_${selectedTemplate.competencies.length+1}`,name:'',description:'',weight:0});rerender()};document.getElementById('apAddRating').onclick=()=>{syncTemplate();selectedTemplate.ratingScale.push({value:selectedTemplate.ratingScale.length+1,label:'',description:''});rerender()};rerender();document.getElementById('apTemplateForm').onsubmit=saveTemplate}
  async function saveTemplate(event){event.preventDefault();syncTemplate();const data=new FormData(event.currentTarget);const body={name:String(data.get('name')||'').trim(),description:String(data.get('description')||''),goalWeight:Number(data.get('goalWeight')),competencyWeight:Number(data.get('competencyWeight')),employeeSelfAssessment:data.get('employeeSelfAssessment')==='on',employeeAcknowledgment:data.get('employeeAcknowledgment')==='on',active:data.get('active')==='on',competencies:selectedTemplate.competencies,ratingScale:selectedTemplate.ratingScale};try{if(selectedTemplate.id)await api(`/api/admin/employee-performance/templates/${encodeURIComponent(selectedTemplate.id)}`,{method:'PATCH',body:JSON.stringify(body)});else await api('/api/admin/employee-performance/templates',{method:'POST',body:JSON.stringify(body)});closeModal();await load();setStatus('Performance review template saved.')}catch(error){alert(error.message)}}

  function scheduleInstall(){if(installScheduled)return;installScheduled=true;requestAnimationFrame(()=>{installScheduled=false;installOverlay();installButtons();if(location.hash==='#employeePerformance'&&!document.getElementById('employeePerformanceOverlay').classList.contains('open'))openCenter()})}
  document.addEventListener('click',event=>{const row=event.target.closest('tr[data-employee]');if(row)selectedEmployeeId=row.dataset.employee},true);
  const observer=new MutationObserver(scheduleInstall);observer.observe(document.documentElement,{childList:true,subtree:true});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',scheduleInstall,{once:true});else scheduleInstall();
})();
